/bin/bash -lc "python3 - <<'PY'
p='Task.v';s=open(p).read();a=s.index('Ltac rewrite_open');b=s.index('Lemma replace_intro_e',a);s=s[:a]+'''Ltac rewrite_open :=
  unfold open_ee, open_te, open_qe, open_tqt, open_qqt;
  first [rewrite replace_open_e_e by assumption | rewrite replace_open_e_t by assumption |
         rewrite replace_open_e_q by assumption | rewrite replace_open_qt_t by assumption |
         rewrite replace_open_qt_q by assumption];
  try rewrite replace_e_fresh by solve_notin;
  try rewrite replace_qt_fresh by solve_notin;
  simpl; destruct (X == X); congruence.

'''+s[b:];s=s.replace('  simpl; destruct (X == X); congruence.', '''  simpl; match goal with |- context[if ?x == ?x then _ else _] =>
    destruct (x == x); congruence end.''');open(p,'w').write(s)
PY
make"

